<script lang="ts">
	import {formatDate, nextStep, type JourneyEvent} from '$lib/request-flow';
	import { requestTimeline } from '$lib/student-request-display';
	let {status, dateRequested, history = [], hasFile = false, completed: completedAt = false, openByDefault = false, compact = false}: {status:string;dateRequested:string;history?:JourneyEvent[];hasFile?:boolean;completed?:boolean;openByDefault?:boolean;compact?:boolean} = $props();
	const completed = $derived(completedAt || history.some(event => event.new_status === 'Completed'));
	const steps = $derived(requestTimeline(status, dateRequested, history, hasFile, completed));
	let userExpanded = $state<boolean | null>(null);
	const expanded = $derived(userExpanded ?? openByDefault);
	const id = $props.id();
</script>
<div class="journey" class:compact>{#if !compact}<p class="font-medium">{completed ? 'Completed' : status==='Correction Requested' ? 'Your next step' : status==='Approved' ? 'Ready for release' : 'What happens next'}</p><p class="journey-help">{nextStep(status,completed,hasFile)}</p><button type="button" class="journey-toggle" aria-expanded={expanded} aria-controls={id} onclick={()=>userExpanded=!expanded}><i class="fa-solid {expanded?'fa-chevron-up':'fa-chevron-down'}" aria-hidden="true"></i>Request timeline</button>{/if}{#if expanded || compact}<ol {id} class="request-stepper">{#each steps as step}<li data-step-state={step.state}><span class="step-dot" aria-hidden="true"></span><div><span class="step-label">{step.label}</span><span class="sr-only"> · {step.state}</span>{#if step.date && !compact}<span class="step-meta">{formatDate(step.date)}</span>{/if}{#if step.actor && !compact}<span class="step-meta">{step.actor}</span>{/if}</div></li>{/each}</ol>{/if}</div>
<style>.journey {padding:var(--space-4);border:1px solid var(--color-border);border-radius:var(--radius-control);background:var(--color-surface-muted);} .journey-help,.step-meta {font-size:var(--type-helper);color:var(--color-text-muted);} .journey-toggle {display:flex;align-items:center;gap:var(--space-2);min-height:40px;color:var(--color-primary);font-size:var(--type-helper);} .request-stepper {display:flex;gap:var(--space-4);padding-top:var(--space-3);} .request-stepper li {position:relative;flex:1;display:flex;flex-direction:column;gap:var(--space-2);font-size:var(--type-helper);min-width:0;} .request-stepper li:not(:last-child)::after {position:absolute;content:'';top:7px;left:20px;right:0;height:2px;background:var(--color-border-strong);} .step-dot {position:relative;z-index:1;width:16px;height:16px;border:2px solid var(--color-border-strong);border-radius:var(--radius-pill);background:var(--color-border-strong);} [data-step-state='done'] .step-dot {border-color:var(--color-primary);background:var(--color-primary);} [data-step-state='current'] .step-dot {border-color:var(--color-primary);background:var(--color-surface);box-shadow:var(--focus-ring);} [data-step-state='current'] .step-label {color:var(--color-primary);font-weight:var(--weight-semibold);} .step-meta {display:block;margin-top:var(--space-1);} .compact {padding:0;border:0;background:none;} @media(max-width:767px){.request-stepper {flex-direction:column;} .request-stepper li {flex-direction:row;gap:var(--space-3);min-height:44px;} .request-stepper li:not(:last-child)::after {top:20px;left:7px;bottom:-8px;right:auto;width:2px;height:auto;} .step-dot {flex-shrink:0;margin-top:2px;}}@media(pointer:coarse){.journey-toggle{min-height:44px;}}</style>
